def largestEndOf132(nums):
    stack = []
    third = 0      # best '2' value found in the suffix (values are >= 1)
    best = -1
    for i in range(len(nums) - 1, -1, -1):
        x = nums[i]
        if x < third:
            best = max(best, third)
        while stack and stack[-1] < x:
            third = max(third, stack.pop())
        stack.append(x)
    return best
